function authScreen(){
 const tabs=[['login','Inloggen'],['signup','Account maken'],...inviteRequired?[['request','Toegang aanvragen']]:[]],password=(id,label,auto,min)=>`<div><label for="${id}">${label}</label><input id="${id}" type="password" autocomplete="${auto}" ${min?`minlength="${min}"`:''} required></div>`;
 const forms={
  login:`<form id="login-form" class="stack"><h2>Welkom terug</h2><div><label for="login">E-mailadres (ouder) of gebruikersnaam (kind)</label><input id="login" autocomplete="username" autocapitalize="none" spellcheck="false" required></div>${password('password','Wachtwoord','current-password')}<button>Inloggen →</button><p id="auth-error" role="alert" class="danger"></p><small>Wachtwoord vergeten? Ouders gebruiken hun herstelcode: ${btn('wachtwoord herstellen','auth-view','link','data-view="recover" type="button"')}. Kinderen vragen hun ouder om een nieuw wachtwoord.</small></form>`,
  signup:`<form id="signup-form" class="stack"><h2>Maak jullie gezinsaccount</h2><p class="muted" style="margin:0">Voor ouders en verzorgers. Daarna geef je ieder kind een eigen login. Gratis tijdens de proefperiode.</p><div><label for="email">Jouw e-mailadres</label><input id="email" type="email" autocomplete="email" required></div>${password('new-password','Wachtwoord (minimaal 10 tekens)','new-password',10)}${password('confirm','Herhaal het wachtwoord','new-password',10)}<div><label for="child-name">Naam of bijnaam van je kind</label><input id="child-name" maxlength="40" placeholder="Bijvoorbeeld: Sam" required></div><div class="grid">${schoolSelects('signup',{year:2})}</div>${inviteRequired?`<div><label for="invite">Uitnodigingscode</label><input id="invite" autocomplete="off" autocapitalize="characters" value="${esc(inviteFromLink)}"><small>Is je aanvraag goedgekeurd? Dan is de code niet nodig: gebruik het e-mailadres van je aanvraag. Nog geen uitnodiging? ${btn('Vraag toegang aan','auth-view','link','data-view="request" type="button"')}.</small></div>`:''}<label class="checkline"><input type="checkbox" id="accept" required><span>Ik ben ouder of verzorger en ga akkoord met de <a href="/voorwaarden.html" target="_blank">voorwaarden</a> en het <a href="/privacy.html" target="_blank">privacybeleid</a>.</span></label><button>Account maken →</button><p id="auth-error" role="alert" class="danger"></p></form>`,
  request:requestSent?`<div class="stack"><span class="eyebrow">AANVRAAG ONTVANGEN</span><h2>Bedankt!</h2><p class="muted" style="margin:0">We bekijken je aanvraag zo snel mogelijk. Is hij goedgekeurd, dan krijg je bericht en maak je bij <i>Account maken</i> je gezinsaccount aan met hetzelfde e-mailadres.</p>${btn('Terug naar inloggen','auth-view','secondary','data-view="login"')}</div>`:`<form id="request-form" class="stack"><h2>Toegang aanvragen</h2><p class="muted" style="margin:0">Leerstap is nog in een besloten proef. Laat je gegevens achter; na goedkeuring kun je met dit e-mailadres een gezinsaccount maken.</p><div><label for="request-name">Je naam</label><input id="request-name" autocomplete="name" maxlength="60" required></div><div><label for="request-email">Je e-mailadres</label><input id="request-email" type="email" autocomplete="email" required></div><div><label for="request-message">Iets over jullie (optioneel)</label><textarea id="request-message" maxlength="500" placeholder="Bijvoorbeeld: zoon in 2 havo, vooral wiskunde en Engels"></textarea></div><div hidden><label for="request-website">Website</label><input id="request-website" tabindex="-1" autocomplete="off"></div><small>We gebruiken je naam en e-mailadres alleen om je aanvraag af te handelen. Zie het <a href="/privacy.html" target="_blank">privacybeleid</a>.</small><button>Aanvraag versturen →</button><p id="auth-error" role="alert" class="danger"></p></form>`,
  recover:`<form id="recover-form" class="stack"><h2>Wachtwoord herstellen</h2><p class="muted" style="margin:0">Gebruik de herstelcode die je kreeg bij het aanmaken van je account.</p><div><label for="recover-email">E-mailadres</label><input id="recover-email" type="email" autocomplete="email" required></div><div><label for="recover-code">Herstelcode</label><input id="recover-code" autocomplete="off" autocapitalize="characters" placeholder="XXXXX-XXXXX-XXXXX-XXXXX" required></div>${password('new-password','Nieuw wachtwoord (minimaal 10 tekens)','new-password',10)}${password('confirm','Herhaal het wachtwoord','new-password',10)}<button>Nieuw wachtwoord instellen →</button><p id="auth-error" role="alert" class="danger"></p></form>`};
 const recovery=`<div class="stack"><span class="eyebrow">BELANGRIJK</span><h2>Bewaar je herstelcode</h2><p class="muted" style="margin:0">Hiermee stel je een nieuw wachtwoord in als je het vergeet. We tonen de code maar één keer en kunnen hem niet opnieuw opvragen.</p><div class="recovery-code" id="recovery-code">${esc(recoveryShown)}</div><div class="row">${btn('Kopiëren','copy-recovery','secondary small')}${btn('Downloaden','download-recovery','secondary small')}</div><label class="checkline"><input type="checkbox" id="recovery-saved"><span>Ik heb de herstelcode veilig bewaard.</span></label>${btn('Verder naar Leerstap →','recovery-done')}</div>`;
 root.innerHTML=`<div class="lockscreen">${intro}<section class="lock-form">${recoveryShown?recovery:`<div class="tabs">${tabs.map(([v,t])=>btn(t,'auth-view',authView===v?'':'secondary',`data-view="${v}"`)).join('')}</div>${forms[authView]}<div class="auth-alt">${btn('Bekijk eerst de voorbeeldles, zonder account','demo','ghost')}</div>${authLinks}`}</section></div>`;
}
async function authSubmit(form){
 const v=id=>$('#'+id)?.value??'',err=$('#auth-error');err.textContent='';
 if(form==='login-form'){await call('POST','/api/login',{login:v('login').trim(),password:v('password')});await loadState();route='home';render();return;}
 if(form==='request-form'){await call('POST','/api/request-access',{name:v('request-name').trim(),email:v('request-email').trim(),message:v('request-message').trim(),website:v('request-website')});requestSent=true;authScreen();return;}
 if(v('new-password')!==v('confirm'))throw Error('De wachtwoorden zijn niet gelijk.');
 if(form==='signup-form'){const r=await call('POST','/api/signup',{email:v('email').trim(),password:v('new-password'),childName:v('child-name').trim(),schoolType:v('signup-type'),year:Number(v('signup-year')),invite:v('invite'),accept:$('#accept').checked});recoveryShown=r.recoveryCode;authScreen();return;}
 if(form==='recover-form'){const r=await call('POST','/api/recover',{email:v('recover-email').trim(),code:v('recover-code'),password:v('new-password')});recoveryShown=r.recoveryCode;authScreen();toast('Je wachtwoord is gewijzigd. Je hebt een nieuwe herstelcode.');}
}
