 validateState(incoming);toast('Back-up wordt overgezet…');
 const r=await call('POST','/api/import',{profiles:incoming.profiles,modules:incoming.modules,attempts:incoming.attempts});let failed=0;
 for(const {pages,data,...meta} of incoming.documents){try{await call('POST','/api/documents',{meta,pages,data});}catch{failed++;}}
 await loadState();route='home';render();toast(`Overgezet: ${incoming.profiles.length} leerling(en), ${incoming.modules.length} leermodule(s), ${incoming.attempts.length} resultaat/resultaten${r.skipped?`, ${r.skipped} al aanwezig`:''}${failed?`. ${failed} bron(nen) lukten niet`:''}.`);
