const openBackup=async(envelope,password)=>{try{return (await decrypt(envelope,password)).state;}catch{throw Error('Openen lukt niet. Controleer het bestand en het wachtwoord.');}};
async function recordAnswer(){if(!state.draft||!$('#answer'))return;state.draft.answers[questionIndex]={answer:$('#answer').value,steps:$('#steps')?.value||''};await save();}
function selectedQuestions(mode){const m=state.modules.find(m=>m.id===$('#module-select')?.value)||activeModule();if(!m.approved)throw Error('Geef de module eerst vrij.');
 const boxes=[...document.querySelectorAll('input[name=chapter]')],chapters=boxes.length?boxes.filter(b=>b.checked).map(b=>Number(b.value)):null;if(chapters&&!chapters.length)throw Error('Kies minstens één paragraaf.');
 const goalBoxes=[...document.querySelectorAll('input[name=goal]')],off=new Set(goalBoxes.filter(b=>!b.checked).map(b=>b.dataset.chapter+'|'+b.value)),done=$('#skip-mastered')?.checked?masteredIds(state.attempts,profile):new Set();
 const chosen=questionsIn(m,chapters).filter(q=>!off.has(questionChapter(m,q)+'|'+q.goal)&&!done.has(q.id));if(!chosen.length)throw Error(done.size?'Alles wat je koos beheers je al. Zet meer onderwerpen aan, of zet „Sla over wat ik al beheers” uit.':'Kies minstens één onderwerp.');
 const level=$('#difficulty')?.value||'adaptief',count=Number($('#count')?.value??5),scoped={...m,questions:chosen};
 if(mode==='drill')return {m,questions:chosen};
 // In a test the word lists of the same chapter come along, mixed in after the other questions like on paper.
 const words=mode==='test'?[...document.querySelectorAll('input[name=test-list]:checked')].flatMap(b=>{const w=state.wordlists.find(x=>x.id===b.value);if(!w)return [];const all=wordQuestions(w,w.cols?'all':'both').map(q=>[Math.random(),q]).sort((x,y)=>x[0]-y[0]).map(x=>x[1]),n=Number($('#test-words-count')?.value??10);return n?all.slice(0,n):all;}):[];
 if(mode==='test'&&!chosen.length&&!words.length)throw Error('Kies minstens één onderwerp of woordenlijst.');
 if(level==='realistic')return {m,questions:[...chooseTest(scoped,null,count),...words]};
 if(mode==='test')return {m,questions:[...chooseQuestions(scoped,state.attempts,profile,level,count||999),...words]};
 return {m,questions:chooseQuestions(scoped,state.attempts,profile,level,count||999)};}
async function finish(early=false){await recordAnswer();const d=structuredClone(state.draft);delete d.pool;delete d.drill;delete d.recent;if(early||d.mode==='drill'){const indices=d.questions.map((q,i)=>i).filter(i=>d.results?.[i]);if(!indices.length){toast('Beantwoord eerst een vraag, of ga later verder.');return;}d.questions=indices.map(i=>d.questions[i]);d.answers=indices.map(i=>d.answers[i]);d.results=indices.map(i=>d.results[i]);}const results=d.questions.map((q,i)=>d.results?.[i]||grade(q,d.answers[i]?.answer||'',d.answers[i]?.steps||''));recordAttempt(d,results);
 state.draft=null;practiceResult=null;await save();route='progress';render();}
