document.addEventListener('submit',e=>{const form=e.target.id;if(!['login-form','signup-form','recover-form','request-form'].includes(form))return;e.preventDefault();const b=e.submitter;if(b)b.disabled=true;authSubmit(form).catch(err=>{const box=$('#auth-error');if(box)box.textContent=err.message;else toast(err.message);}).finally(()=>{if(b)b.disabled=false;});});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el)action(el).catch(e=>toast(e.message||'Dit lukte niet. Je gegevens zijn behouden.'));});
document.addEventListener('change',async e=>{try{if(e.target.classList.contains('wl-all')){const g=e.target.dataset.group;document.querySelectorAll(g===undefined?'input[name=wl-doc],.wl-all':`input[name=wl-doc][data-group="${g}"]`).forEach(x=>x.checked=e.target.checked);return;}if(e.target.id==='profile'){await recordAnswer();drafts[profile]=state.draft;profile=e.target.value;state.draft=drafts[profile]||null;questionIndex=0;practiceResult=null;render();}if(e.target.tagName==='SELECT'&&e.target.value==='__new'){const name=(prompt('Welk vak? Bijvoorbeeld: Natuur & techniek')||'').trim().slice(0,80);if(!name){e.target.value='';return;}const o=new Option(name,name,true,true);e.target.add(o,e.target.options.length-1);if(e.target.id==='up-subject')uploadTarget={...(uploadTarget||{}),subject:name};}if(e.target.name==='read-mode'){try{localStorage.setItem('leerstap-read',e.target.value);}catch{}toast(e.target.value==='ai'?'Foto’s worden voortaan door de AI gelezen.':'Foto’s worden voortaan op dit apparaat gelezen.');}if(e.target.id==='module-select'){selected=e.target.value;if(['practice','test'].includes(route))render();}if(e.target.name==='chapter')document.querySelectorAll(`input[name=goal][data-chapter="${e.target.value}"]`).forEach(b=>b.checked=e.target.checked);if(e.target.id==='archive-subject'){archiveSubject=e.target.value;render();}if(e.target.id==='archive-year'){archiveYear=e.target.value;render();}if(e.target.id==='archive-period'){archivePeriod=e.target.value;render();}if(e.target.id==='files'){const files=[...e.target.files];let meta;try{meta=uploadMeta();}catch(err){e.target.value='';throw err;}e.target.disabled=true;await addFiles(files,meta);}if(e.target.classList.contains('map-files')){const mp=maps()[Number(e.target.dataset.map)],first=mp.docs[0];await addFiles([...e.target.files],{subject:mp.subject==='Zonder vak'?'':mp.subject,chapter:mp.chapter,schoolYear:first.schoolYear,period:first.period,method:first.method});}}catch(err){toast(err.message);}});
// Typing saves after a short pause instead of on every key.
let typingTimer;document.addEventListener('input',e=>{if(['answer','steps'].includes(e.target.id)){clearTimeout(typingTimer);typingTimer=setTimeout(()=>recordAnswer().catch(()=>{}),800);}});
window.addEventListener('beforeunload',e=>{if(state&&!ephemeral&&saveStatus!=='ok'){e.preventDefault();e.returnValue='';}});
window.addEventListener('online',()=>{if(saveStatus==='error')save().catch(()=>{});});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;if(state)render();});
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
async function start(){
 // An invitation link (?uitnodiging=CODE) opens the signup form with the code filled in.
 const invited=new URLSearchParams(location.search).get('uitnodiging');if(invited){inviteFromLink=invited.trim().toUpperCase().slice(0,40);authView='signup';history.replaceState(null,'',location.pathname);}
 try{const s=await call('GET','/api/status');ai=s.configured;inviteRequired=s.inviteRequired;}catch{}
 storage('get').then(v=>{oldVault=v?.format==='leerstap-v1'?v:null;}).catch(()=>{});
 try{if((await call('GET','/api/session')).user){await loadState();render();return;}}
 catch(e){if(e.status===0){root.innerHTML=`<div class="lockscreen">${intro}<section class="lock-form"><h2>Geen verbinding</h2><p class="muted">Leerstap kan de server niet bereiken. Controleer je internetverbinding.</p>${btn('Opnieuw proberen','retry')}<div class="auth-alt">${btn('Bekijk de voorbeeldles','demo','ghost')}</div></section></div>`;return;}}
 authScreen();
}
start();
